  <div class="sub-container">
    <zs-table
      ref="table"
      :data="mdetailedreturnList"
      :table-tr="0"
      row-key="busiNo"
    >
      <el-table-column
        type="index"
        label="序号"
        width="60"
        disabled
      />
      <el-table-column
        label="交易类型"
        prop="tradeType"
        :formatter="dictFormatter"
      />
      <el-table-column
        label="交易金额"
        prop="amount"
      />
      <el-table-column
        label="交易时间"
        prop="docTime"
        :formatter="formatters.dateFormatter"
      />
      <el-table-column
        label="业务编号"
        prop="busiNo"
      />
    </zs-table>
    <pagination
      v-show="total>0"
      :total="total"
      :page.sync="queryParams.pageNum"
      :limit.sync="queryParams.pageSize"
      @pagination="getList"
    />
  </div>
</template>

<script>
import { getDetailedList } from '@/api/estate/ksmoquerecord'
const debounce = require('lodash/debounce')
import listMixins from '@/mixins/listMixins'

export default {
  name: 'MdetailedReturn',
  mixins: [listMixins],
  data() {
    return {
      tradeTypeOptions:[],
      // 昆山账户交易明细信息表格数据
      mdetailedreturnList: [],
      // 查询参数
      queryParams: {
        pageNum: 1,
        pageSize: 10,
        forqueryaccountId: this.getId(),
      }
    }
  },
  created() {
    this.init()
  },
  methods: {
    // 初始化列表页
    init() {
      this.initDict()
      this.getList()
    },
    initDict() {
      this.getDicts('t_mf_KS_TradeType').then(response => {
        this.tradeTypeOptions = response.data
      })
    },
    /** 查询昆山账户交易明细信息列表 */
    getList: debounce(function () {
      getDetailedList(this.queryParams).then(response => {
        this.mdetailedreturnList = response.rows
        this.total = response.total
      })
    }, 500)
  }
}
</script>
